const container = document.getElementById("produk-container");

function tampilkanProduk(dataProduk) {
  container.innerHTML = "";

  dataProduk.forEach(item => {
    container.innerHTML += `
      <div class="produk-card">
        <img src="${item.gambar}" alt="${item.nama}">
        <h3>${item.nama}</h3>
        <p>${item.deskripsi}</p>
        <strong>Rp ${item.harga.toLocaleString("id-ID")}</strong>
      </div>
    `;
  });
}

// tampilkan semua produk saat halaman dibuka
tampilkanProduk(produk);


function filterProduk(kategori) {
  if (kategori === "all") {
    tampilkanProduk(produk);
  } else {
    const hasilFilter = produk.filter(item => item.kategori === kategori);
    tampilkanProduk(hasilFilter);
  }
}

